VectorColumnIndexer::Ptr SegmentImpl::get_memory_vector_indexer(
    const std::string &field_name) {
  auto iter = memory_vector_indexers_.find(field_name);
  if (iter != memory_vector_indexers_.end()) {
    return iter->second;
  }
  return nullptr;
}

